mapper.select:
SELECT id, workspace_id, task_id, title, description, req_id, req_name, req_doc_id, req_doc_title,
       owner, owner_user_id, category, priority, start_date, completed_at,
       first_started_at, last_ended_at, total_minutes, created_at
FROM task_completion_record
WHERE workspace_id = #{workspaceId}
  AND completed_at >= #{from}
  AND completed_at < #{to}
ORDER BY completed_at DESC, id DESC
